// d36: the real VerticalVersion.speakerClips and VerticalVersion.plan on a fixture, no app window.
import AppKit

let SEC: Int64 = 600_000
let STEP: Int64 = 60_000

func mic(_ id: Int, _ track: Int, _ start: Int64, _ dur: Int64) -> [String: Any] {
    ["id": id, "track": track, "start": start * SEC, "duration": dur * SEC,
     "source": ["kind": "media", "media": 2, "in": start * SEC] as [String: Any]]
}

func project(_ clips: [[String: Any]]) throws -> ReelProject {
    let wide: [String: Any] = [
        "id": 3, "track": 21, "start": 0, "duration": 10 * SEC,
        "source": ["kind": "media", "media": 1, "in": 0] as [String: Any], "video": [:] as [String: Any],
    ]
    let doc: [String: Any] = [
        "canvas": ["width": 1920, "height": 1080, "fps": [30, 1]] as [String: Any],
        "media": [
            ["id": 1, "path": "/wide.mov", "kind": "video", "duration": 40 * SEC, "width": 1920,
             "height": 1080, "fps": [30, 1], "has_video": true] as [String: Any],
            ["id": 2, "path": "/mic.wav", "kind": "audio", "duration": 40 * SEC, "has_audio": true]
                as [String: Any],
        ],
        "tracks": [["id": 20], ["id": 21], ["id": 22], ["id": 23], ["id": 24]],
        "clips": [wide] + clips,
        "next_id": 100,
    ]
    let data = try JSONSerialization.data(withJSONObject: doc)
    return try ReelProject.from(json: String(decoding: data, as: UTF8.self))
}

func mute(_ p: ReelProject, _ clip: UInt32) throws -> ReelProject {
    guard case .applied(let made) = try p.applying(.setEnabled(clip: clip, audio: false)) else {
        fatalError("set_enabled did not apply")
    }
    return made
}

func subjects(_ first: UInt32, _ second: UInt32) -> [String: Any] {
    // The first speaker talks 0-8 s or the second, face 1 and face 2 mouths moving with them.
    var samples: [[String: Any]] = []
    for n in 0...100 {
        let firstTalks = n < 50
        func face(_ cx: Double, _ talks: Bool) -> [String: Any] {
            ["x": cx - 0.04, "y": 0.33, "w": 0.08, "h": 0.14, "c": 0.9,
             "mouth": talks && n % 2 == 1 ? 0.20 : 0.05]
        }
        samples.append(["t": Int64(n) * STEP, "faces": [face(0.42, firstTalks), face(0.58, !firstTalks)]])
    }
    return ["samples": samples, "shots": [] as [Int],
            "turns": [["from": 0, "to": 5 * SEC, "mic": Int(first)],
                      ["from": 5 * SEC, "to": 10 * SEC, "mic": Int(second)]]]
}

func report(_ title: String, _ p: ReelProject, mics: [UInt32], faces: [UInt32]?) throws {
    print("== \(title)")
    let settings = VerticalSettings(
        shape: .tall, follow: .speaker, zoom: 1, whereEmpty: .fit, mics: mics, micFaces: faces)
    let chosen = VerticalVersion.speakerClips(p, settings: settings, missing: [])
    print("speakerClips:", chosen.map { "clip \($0.clip) mics \($0.mics) faces \(String(describing: $0.micFaces))" })
    guard let own = chosen.first else { return }
    let turns = subjects(own.mics[0], own.mics[1])
    switch try VerticalVersion.plan(p, settings: settings, subjects: [3: turns], missing: []) {
    case .refused(let why): print("plan refused:", why)
    case .plan(let plan):
        print("speaker-framed:", plan.speaker.map(\.clip))
        for entry in plan.entries where entry.clip == 3 {
            print("entry:", entry.treatment, entry.reason ?? "nil")
        }
        print("summary:", VerticalVersion.summary(plan))
    }
}

// (1) One microphone track split: 0-8 s muted, 8-10 s sounding. The sheet's mic is the sounding one.
var one = try project([mic(4, 22, 0, 8), mic(7, 22, 8, 2), mic(5, 23, 0, 10)])
one = try mute(one, 4)
print("microphones offered:", VerticalVersion.microphones(one).map { "\($0.track)->\($0.clip)" })
try report("split track, long piece muted", one, mics: [7, 5], faces: [1, 2])

// (2) The same with nothing muted: the control.
let control = try project([mic(4, 22, 0, 8), mic(7, 22, 8, 2), mic(5, 23, 0, 10)])
try report("control, nothing muted", control, mics: [7, 5], faces: [1, 2])

// (3) Sounding piece longer than the muted one: the muted piece is not picked.
var longer = try project([mic(4, 22, 0, 2), mic(7, 22, 2, 8), mic(5, 23, 0, 10)])
longer = try mute(longer, 4)
try report("muted piece shorter", longer, mics: [7, 5], faces: [1, 2])

// (4) Three mics, the third's only clip under the shot muted, its sounding clip past the shot.
var three = try project([mic(4, 22, 0, 10), mic(5, 23, 0, 10), mic(6, 24, 0, 10), mic(8, 24, 12, 3)])
three = try mute(three, 6)
print("microphones offered:", VerticalVersion.microphones(three).map { "\($0.track)->\($0.clip)" })
try report("third mic muted under the shot", three, mics: [4, 5, 8], faces: [1, 2, 3])

// (5) Two mics, the second muted under the shot: does the muted track count toward the two?
var two = try project([mic(4, 22, 0, 10), mic(5, 23, 0, 10), mic(8, 23, 12, 3)])
two = try mute(two, 5)
try report("second mic muted under the shot", two, mics: [4, 8], faces: [1, 2])

